static void list_set_gc ( struct timer_list * t ) { struct list_set * map = from_timer ( map , t , gc ) ; struct ip_set * set = map -> set ; spin_lock_bh ( & set -> lock ) ; set_cleanup_entries ( set ) ; spin_unlock_bh ( & set -> lock ) ; map -> gc . expires = jiffies + IPSET_GC_PERIOD ( set -> timeout ) * HZ ; } 